insert into public.lessons (slug, number, title, topic, chapter, status, video_id, duration, level, hook, summary, outcomes, skills, theorem, explanation, figure, us_name, textbook_envision, textbook_bigideas, textbook_hmh, standard, textbook_confirmed) values ('angle-of-elevation-great-zimbabwe', '8.1', 'Angle of elevation at Great Zimbabwe', 'Trigonometry', 'Chapter 8 · Trigonometry', 'live', '3gDGAKZOnBY', '2:08', 'Forms 3 and 4', 'A tourist stands in front of the Great Enclosure at Great Zimbabwe and looks up at the Zimbabwe Bird on top of the wall. How far does his gaze tilt above the horizontal?', 'What an angle of elevation is, how the horizontal line of sight is drawn from the observer''s eye, and how the tangent ratio turns two distances into an angle.', 'What an angle of elevation means
How the horizontal line of sight is drawn from the observer''s eye
How the angle of elevation forms a right-angled triangle
How to identify the opposite and adjacent sides
How to calculate the angle with the tangent ratio and its inverse', 'Trigonometry, Tangent ratio, Right-angled triangles, Angles of elevation, Inverse tan, Problem solving', 'The angle of elevation is the angle between the horizontal line of sight and the line from the observer''s eye up to the object. In the right-angled triangle it makes, tan θ = opposite ÷ adjacent.', 'Start at the observer''s eye and draw a horizontal line. That is the reference line. Now draw the line of sight from the eye up to the object. The angle between the two is the angle of elevation. Drop a vertical from the object to the horizontal line and you have a right-angled triangle: the vertical side (how far the object is above eye level) is opposite the angle, and the horizontal side (how far away the observer stands) is adjacent to it. The tangent ratio links them: tan θ = opposite ÷ adjacent. In the video the Zimbabwe Bird is 10 m above the tourist''s eye and he stands 15 m from the wall, so tan θ = 10 ÷ 15 and θ = tan⁻¹(10 ÷ 15) ≈ 33.7°. The measurements are illustrative.', 'assets/figures/elevation-theorem.svg', 'Angles of elevation and depression; solving right triangles with the tangent ratio', 'Topic 8 Right Triangles and Trigonometry · Trigonometric Ratios', 'Chapter 9 Right Triangles and Trigonometry · The Tangent Ratio', 'Right Triangles and Trigonometry unit · Tangent Ratio', 'HSG-SRT.C.8', false)
  on conflict (slug) do update set number = excluded.number, title = excluded.title, topic = excluded.topic, chapter = excluded.chapter, status = excluded.status, video_id = excluded.video_id, duration = excluded.duration, level = excluded.level, hook = excluded.hook, summary = excluded.summary, outcomes = excluded.outcomes, skills = excluded.skills, theorem = excluded.theorem, explanation = excluded.explanation, figure = excluded.figure, us_name = excluded.us_name, textbook_envision = excluded.textbook_envision, textbook_bigideas = excluded.textbook_bigideas, textbook_hmh = excluded.textbook_hmh, standard = excluded.standard, textbook_confirmed = excluded.textbook_confirmed, updated_at = now();
delete from public.questions where lesson_id = (select id from public.lessons where slug = 'angle-of-elevation-great-zimbabwe');
insert into public.questions (lesson_id, position, prompt, answer, tolerance, unit, hint, solution, figure)
  values ((select id from public.lessons where slug = 'angle-of-elevation-great-zimbabwe'), 1, 'As in the video: the tourist stands 15 m from the wall and the Zimbabwe Bird is 10 m above his eye level. Find the angle of elevation, to 1 decimal place.', 33.7, 0.15, '°', 'Which side is opposite the angle, and which is adjacent? Then tan θ = opposite ÷ adjacent.', 'Opposite = 10 m (height above eye level), adjacent = 15 m (distance from the wall). tan θ = 10 ÷ 15 = 0.6667, so θ = tan⁻¹(0.6667) ≈ 33.7°.', 'assets/figures/elevation-q1.svg');
insert into public.questions (lesson_id, position, prompt, answer, tolerance, unit, hint, solution, figure)
  values ((select id from public.lessons where slug = 'angle-of-elevation-great-zimbabwe'), 2, 'The tourist moves to a spot 24 m from the wall. From there the top of the wall is 18 m above his eye level. Find the angle of elevation to the top of the wall, to 1 decimal place.', 36.9, 0.15, '°', 'Same triangle, new numbers. The height above eye level is opposite; the distance from the wall is adjacent.', 'tan θ = 18 ÷ 24 = 0.75, so θ = tan⁻¹(0.75) ≈ 36.9°.', 'assets/figures/elevation-q2.svg');
insert into public.questions (lesson_id, position, prompt, answer, tolerance, unit, hint, solution, figure)
  values ((select id from public.lessons where slug = 'angle-of-elevation-great-zimbabwe'), 3, 'From 20 m away, a visitor measures the angle of elevation to a flag on the wall as 40°. How far above her eye level is the flag? Give your answer in metres to 1 decimal place.', 16.8, 0.15, 'm', 'This time you know the angle and the adjacent side. Rearrange tan θ = opposite ÷ adjacent to find the opposite side.', 'opposite = adjacent × tan θ = 20 × tan 40° = 20 × 0.8391 ≈ 16.8 m.', 'assets/figures/elevation-q3.svg');
insert into public.questions (lesson_id, position, prompt, answer, tolerance, unit, hint, solution, figure)
  values ((select id from public.lessons where slug = 'angle-of-elevation-great-zimbabwe'), 4, 'Back at the first spot (15 m from the wall, angle of elevation 33.7°), the tourist''s eye is 1.6 m above the ground. How high above the ground is the Zimbabwe Bird? Give your answer in metres to 1 decimal place.', 11.6, 0.2, 'm', 'The triangle gives the height above the eye. The eye is itself above the ground. Add.', 'Height above eye level = 15 × tan 33.7° ≈ 10.0 m. Add the eye height: 10.0 + 1.6 = 11.6 m above the ground.', 'assets/figures/elevation-q4.svg');
insert into public.questions (lesson_id, position, prompt, answer, tolerance, unit, hint, solution, figure)
  values ((select id from public.lessons where slug = 'angle-of-elevation-great-zimbabwe'), 5, 'The tourist walks forward until he is exactly 10 m from the wall. The Bird is still 10 m above his eye level. What is the angle of elevation now?', 45, 0.15, '°', 'What is tan θ when the opposite and adjacent sides are equal?', 'tan θ = 10 ÷ 10 = 1, and the angle whose tangent is 1 is 45°. Walking closer makes the angle of elevation larger.', 'assets/figures/elevation-q5.svg');
insert into public.lessons (slug, number, title, topic, chapter, status, video_id, duration, level, hook, summary, outcomes, skills, theorem, explanation, figure, us_name, textbook_envision, textbook_bigideas, textbook_hmh, standard, textbook_confirmed) values ('alternate-segment-theorem', '7.5', 'The alternate segment theorem', 'Circles', 'Chapter 7 · Circles', 'live', '', '0:50', 'Forms 3 and 4', 'Draw a tangent to a circle. Draw a chord from the same point. The angle between them is hiding somewhere else on the circle. Watch where.', 'The angle between a tangent and a chord equals the angle in the alternate segment. A 50-second animation, then four questions.', 'State the alternate segment theorem
Spot the alternate segment for a given tangent and chord
Find missing angles using the theorem together with angles on a straight line and in a triangle
Recognise the same result as the tangent-chord angle in US textbooks', 'Circle theorems, Tangents and chords, Inscribed angles, Angle chasing, Geometric reasoning', 'The angle between a tangent and a chord at the point of contact is equal to the angle in the alternate segment.', 'The tangent PQ touches the circle at A. The chord AB cuts the circle into two segments. The angle between AQ and AB equals angle ACB, where C is any point on the arc on the other side of the chord. Why: angle ACB is an inscribed angle, so it is half the arc AB. The tangent-chord angle at A is also half the arc AB, because a tangent is the limit of a chord through A. Two halves of the same arc are equal. US textbooks state the same result as: the measure of the angle formed by a tangent and a chord is half the measure of the intercepted arc.', 'assets/figures/segment-theorem.svg', 'Angle formed by a tangent and a chord is half the intercepted arc', 'Topic 10 Circles · Secants, Tangents and Angle Measures', 'Chapter 10 Circles · Angle Relationships in Circles', 'Circles unit · Angles and Segments in Circles', 'HSG-C.A.2', false)
  on conflict (slug) do update set number = excluded.number, title = excluded.title, topic = excluded.topic, chapter = excluded.chapter, status = excluded.status, video_id = excluded.video_id, duration = excluded.duration, level = excluded.level, hook = excluded.hook, summary = excluded.summary, outcomes = excluded.outcomes, skills = excluded.skills, theorem = excluded.theorem, explanation = excluded.explanation, figure = excluded.figure, us_name = excluded.us_name, textbook_envision = excluded.textbook_envision, textbook_bigideas = excluded.textbook_bigideas, textbook_hmh = excluded.textbook_hmh, standard = excluded.standard, textbook_confirmed = excluded.textbook_confirmed, updated_at = now();
delete from public.questions where lesson_id = (select id from public.lessons where slug = 'alternate-segment-theorem');
insert into public.questions (lesson_id, position, prompt, answer, tolerance, unit, hint, solution, figure)
  values ((select id from public.lessons where slug = 'alternate-segment-theorem'), 1, 'PQ is a tangent to the circle at A. The angle between the tangent AQ and the chord AB is 58°. C is a point on the circle in the alternate segment. Find angle ACB, marked x.', 58, 0.01, '°', 'Which angle sits in the segment on the other side of chord AB?', 'The tangent AQ and the chord AB meet at A with an angle of 58°. By the alternate segment theorem, the angle in the alternate segment is equal to it. Angle ACB stands in that segment, so x = 58°.', 'assets/figures/segment-q1.svg');
insert into public.questions (lesson_id, position, prompt, answer, tolerance, unit, hint, solution, figure)
  values ((select id from public.lessons where slug = 'alternate-segment-theorem'), 2, 'PQ is a tangent at A. Triangle ABC is inscribed in the circle with angle ACB = 41°. Find the angle y between the tangent AQ and the chord AB.', 41, 0.01, '°', 'The theorem works in both directions: the angle in the alternate segment tells you the tangent-chord angle.', 'Angle ACB is in the segment on the opposite side of chord AB from the tangent AQ, so it is the angle in the alternate segment. By the theorem it equals the tangent-chord angle. y = 41°.', 'assets/figures/segment-q2.svg');
insert into public.questions (lesson_id, position, prompt, answer, tolerance, unit, hint, solution, figure)
  values ((select id from public.lessons where slug = 'alternate-segment-theorem'), 3, 'PQ is a tangent at A. Angle PAB = 65° and angle QAC = 47°. Find angle BAC, marked z.', 68, 0.01, '°', 'PAQ is a straight line. What do the three angles at A add up to?', 'PAQ is a straight line, so the angles at A add to 180°. z = 180° − 65° − 47° = 68°. Bonus: the theorem gives the other two angles for free. Angle ACB = angle PAB = 65° and angle ABC = angle QAC = 47°. Check: 68 + 65 + 47 = 180.', 'assets/figures/segment-q3.svg');
insert into public.questions (lesson_id, position, prompt, answer, tolerance, unit, hint, solution, figure)
  values ((select id from public.lessons where slug = 'alternate-segment-theorem'), 4, 'PQ is a tangent at A. The angle between AQ and the chord AB is 52°, and angle ABC = 73°. Find angle BAC, marked w.', 55, 0.01, '°', 'First use the theorem to find angle ACB. Then use the angle sum of triangle ABC.', 'By the alternate segment theorem, angle ACB equals the angle between the tangent AQ and the chord AB, so angle ACB = 52°. In triangle ABC the angles add to 180°: w = 180° − 52° − 73° = 55°.', 'assets/figures/segment-q4.svg');
